function freeze(x){if(x&&typeof x==='object'){Object.values(x).forEach(freeze);Object.freeze(x);}return x;}freeze(data);
const profiles=new Map(data.profiles.map(p=>[p.sourceId,p])),tracks=new Map(data.tracks.map(t=>[t.id,t])),topics=new Map(data.topics.map(t=>[t.id,t]));
